// Code snippets live in src/code/<deck>/<name>.py; their real output is generated by scripts/run-snippets.ts.
const code = import.meta.glob(['../code/**/*.py', '!../code/**/*.sol.py'], { eager: true, query: '?raw', import: 'default' }) as Record<string, string>;
const out = import.meta.glob('../code/**/*.out.txt', { eager: true, query: '?raw', import: 'default' }) as Record<string, string>;
const figures = import.meta.glob('../code/**/*.fig-*.svg', { eager: true, query: '?url', import: 'default' }) as Record<string, string>;
const trace = import.meta.glob('../code/**/*.trace.json', { eager: true, import: 'default' }) as Record<string, Record<string, string>[]>;

export type Snippet = {
  /** file name as shown on the card, e.g. "jumlah.py" */
  file: string;
  code: string;
  /** captured terminal output ('' when the snippet never terminates or prints nothing) */
  out: string;
  trace?: Record<string, string>[];
  /** figures drawn by plt.show(), as image URLs in drawing order */
  figs: string[];
};

/** snip('p05/jumlah') → source, generated output and (optional) variable trace. */
export function snip(id: string): Snippet {
  // <name>.sol.py = instructor solution: its output is shown to students, its source is never bundled
  const src = code[`../code/${id}.py`] ?? (`../code/${id}.sol.out.txt` in out ? '' : undefined);
  if (src === undefined) throw new Error(`Snippet not found: ${id}`);
  const output = out[`../code/${id}.out.txt`] ?? out[`../code/${id}.sol.out.txt`] ?? '';
  const figs = Object.keys(figures).filter((k) => k.startsWith(`../code/${id}.fig-`) || k.startsWith(`../code/${id}.sol.fig-`)).sort((a, b) => a.localeCompare(b, undefined, { numeric: true })).map((k) => figures[k]);
  return { figs, file: `${id.split('/').pop()}.py`, code: src, out: output, trace: trace[`../code/${id}.trace.json`] };
}

const csv = import.meta.glob('../../public/data/*.csv', { eager: true, query: '?raw', import: 'default' }) as Record<string, string>;
/** Text of a data file in public/data, e.g. dataFile('mahasiswa.csv'), shown exactly as it is on disk. */
export function dataFile(name: string): string {
  const text = csv[`../../public/data/${name}`];
  if (text === undefined) throw new Error(`Data file not found: ${name}`);
  return text;
}
